import{_ as t,o as a,c as e,ag as i}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"SetSCARAMode 设置SCARA姿态模式","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetSCARAMode.md","filePath":"3. 指令/5. 设置指令/SetSCARAMode.md","lastUpdated":1778862643000}'),n={name:"3. 指令/5. 设置指令/SetSCARAMode.md"};function o(r,s,d,h,l,p){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="setscaramode-设置scara姿态模式" tabindex="-1">SetSCARAMode 设置SCARA姿态模式 <a class="header-anchor" href="#setscaramode-设置scara姿态模式" aria-label="Permalink to &quot;SetSCARAMode 设置SCARA姿态模式&quot;">​</a></h1><p>该指令专门用于 <strong>SCARA 机器人</strong>，用于解决在执行 <code>MovJCpos</code>（关节空间坐标点运动）时可能出现的<strong>姿态多圈旋转</strong>问题。通过切换该模式，可以决定机器人是严格遵循预设的关节构型，还是优先选择旋转角度最短的路径。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetSCARAMode(SCARAMode) SetSCARAMode(SCARA 模式)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>SCARAMode：SCARA 模式（SCARA Mode）</td><td>enum（枚举型：<code>CfgON</code> / <code>CfgOFF</code>）</td><td>定义姿态规划的逻辑。<br>* <strong>CfgON</strong>：<strong>启用构型限制</strong>。机器人将严格按照点位中记录的关节构型（Config）参数进行运动。在这种模式下，为了达到特定的构型，末端轴（通常是 U 轴/第 4 轴）可能会为了绕开限位或遵循指令而进行超过 360° 的多圈旋转。<br>* <strong>CfgOFF</strong>：<strong>禁用构型限制（最短路径）</strong>。机器人会忽略点位记录的原始构型参数，自动计算当前位置到目标位置之间<strong>旋转弧度最小</strong>的路径。这能有效避免多余的空转，提高节拍。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>SCARA 机器人的末端轴通常具有很大的旋转范围。在自动化生产线上，如果从 350° 运动到 10°，在 <code>CfgON</code> 模式下它可能会反向旋转 340°，而在 <code>CfgOFF</code> 模式下它会跨越零点仅旋转 20°。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSCARAMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CfgOFF&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJCpos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">P1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人将以<strong>最短旋转路径</strong>向 <strong>P1</strong> 点运动，而不考虑 <strong>P1</strong> 点示教时的具体构型参数。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>高速搬运</strong>：在电子元件贴装等循环极快的场景中，使用 <code>CfgOFF</code> 避免末端轴不必要的&quot;绕路&quot;旋转，最大化压缩循环时间。</li><li><strong>理瓶/理料</strong>：工件姿态随机时，通过该指令确保机器人始终以最快方式对准目标。</li><li><strong>注意</strong>：如果在某些特定工艺（如带电缆的工具）中，旋转圈数受到物理线缆限制，则必须使用 <code>CfgON</code> 以防止线缆缠绕断裂。</li></ul>`,18)])])}const k=t(n,[["render",o]]);export{c as __pageData,k as default};
